import{_ as a,o,c as t,ag as r}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Portable Form Host APIs","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/index.md","filePath":"spec/host-api/index.md"}'),i={name:"spec/host-api/index.md"};function n(s,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="portable-form-host-apis" tabindex="-1">Portable Form Host APIs <a class="header-anchor" href="#portable-form-host-apis" aria-label="Permalink to &quot;Portable Form Host APIs&quot;">​</a></h1><h2 id="current-specification-contract-host-api-v1" tabindex="-1">Current Specification contract: Host API v1 <a class="header-anchor" href="#current-specification-contract-host-api-v1" aria-label="Permalink to &quot;Current Specification contract: Host API v1&quot;">​</a></h2><p>Takoform Specification 1.0 defines the literal <code>forms.takoform.com/v1</code> Host API (<a href="./v1.html"><code>v1.md</code></a>):</p><ul><li>discovery: <code>GET /.well-known/takoform/v1</code>;</li><li>API root: <code>/apis/forms.takoform.com/v1</code>;</li><li>wire schema: <a href="/schemas/v1/host-api-wire.schema.json"><code>host-api-wire-v1.schema.json</code></a>;</li><li>operation table: <a href="operations-v1.json"><code>operations-v1.json</code></a>.</li></ul><p>The Specification release candidate remains open until an exact committed source snapshot, the exact multi-family candidate/corpus, and manifest-owned reference conformance are all closed. The lane&#39;s stable name does not promote any current <code>0.x</code> Form to Form <code>1.0.0</code> and does not release Provider 3.</p><h2 id="retained-pre-v1-design-snapshot-host-api-v1beta4" tabindex="-1">Retained pre-v1 design snapshot: Host API v1beta4 <a class="header-anchor" href="#retained-pre-v1-design-snapshot-host-api-v1beta4" aria-label="Permalink to &quot;Retained pre-v1 design snapshot: Host API v1beta4&quot;">​</a></h2><p><a href="./v1beta4.html"><code>v1beta4.md</code></a> and decision <a href="./../decisions/0051-an-unserved-lane-is-withdrawn-not-stacked.html">0051</a> are retained pre-v1 design history. Snapshot-era uses of “current” in those frozen bytes describe that document&#39;s point in time; they do not select today&#39;s Host lane. Decisions <a href="./../decisions/0052-the-specification-is-released-on-its-own-line.html">0052</a> and <a href="./../decisions/0053-specification-and-provider-release-evidence.html">0053</a> supersede their lane-selection and release-authority conclusions. The v1beta4 document is not rewritten into v1 and is not a Specification 1.0 prerequisite.</p><h2 id="retained-provider-2-1-1-lane-host-api-v1beta1" tabindex="-1">Retained Provider 2.1.1 lane: Host API v1beta1 <a class="header-anchor" href="#retained-provider-2-1-1-lane-host-api-v1beta1" aria-label="Permalink to &quot;Retained Provider 2.1.1 lane: Host API v1beta1&quot;">​</a></h2><p>Provider <code>v2.1.1</code> speaks the immutable <code>forms.takoform.com/v1beta1</code> Host API (<a href="./v1beta1.html"><code>v1beta1.md</code></a>):</p><ul><li>discovery: <code>GET /.well-known/takoform/v1beta1</code>;</li><li>API root: <code>/apis/forms.takoform.com/v1beta1</code>;</li><li>wire schema: <a href="/schemas/v1beta1/host-api-wire.schema.json"><code>host-api-wire-v1beta1.schema.json</code></a>;</li><li>operation table: <a href="operations-v1beta1.json"><code>operations-v1beta1.json</code></a>.</li></ul><p>Provider 2.1.1 is the Registry-published retained distribution that carries this protocol. <code>release/version.json</code> intentionally remains <code>publicationStatus: candidate-only</code> descriptor metadata after owner publication; the retained signed Registry readback is the Provider availability evidence. The Beta label here belongs to the Host API, not to Provider 2.1.1 (<a href="./../decisions/0035-beta-contracts-ship-in-stable-provider-v2-1.html">decision 0035</a>).</p><p>The retained protocol serves the literal Edge Form Family <code>edge.forms.takoform.com/v1beta1</code>: 15 individual <code>0.1.0</code> Form definitions, each Experimental. Their retained Form Package envelope is the literal <code>packages.forms.takoform.com/v1alpha4</code>; package artifacts remain unpublished. The nested <code>interfaces.takoform.com/v1alpha1</code> and <code>bindings.takoform.com/v1alpha1</code> identifiers are independent contracts, not Host API maturity labels.</p><p>For the current Specification contract, read <a href="./v1.html"><code>v1.md</code></a>. For the retained Provider contract, read <a href="./v1beta1.html"><code>v1beta1.md</code></a>. Requirement keywords are used as described in <a href="./../conformance.html"><code>../conformance.md</code></a>, and the digest-pinned conformance input for any neutral black-box host runner is <a href="../../conformance/portable-host-v1beta1/contract.json"><code>conformance/portable-host-v1beta1/contract.json</code></a>. The stable suite is rooted at <a href="../../conformance/takoform-v1/manifest.json"><code>conformance/takoform-v1/manifest.json</code></a>.</p><h2 id="withdrawn-pre-beta-lanes" tabindex="-1">Withdrawn pre-Beta lanes <a class="header-anchor" href="#withdrawn-pre-beta-lanes" aria-label="Permalink to &quot;Withdrawn pre-Beta lanes&quot;">​</a></h2><p>Three earlier Host API lanes existed and were withdrawn with their epochs (<a href="./../decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>):</p><ul><li><code>forms.takoform.com/v1alpha1</code>, the Legacy provider-v1 lane at the unversioned <code>/.well-known/takoform</code>;</li><li><code>forms.takoform.com/v1alpha2</code>, the provider-v2 lane at <code>/.well-known/takoform/v1alpha2</code>;</li><li><code>forms.takoform.com/v1alpha3</code>, whose wire the v1beta1 lane carried forward (<a href="./../decisions/0038-a-generation-move-is-measured-not-assumed.html">decision 0038</a>).</li></ul><p>Their normative documents, operation tables, and wire schemas are recorded as retired identities in <a href="../../release/published-document-lanes.json"><code>release/published-document-lanes.json</code></a> and remain readable in this repository&#39;s git history. A withdrawn lane identifier is never reused for a different contract, and published provider releases that speak those lanes (<code>v1.0.3</code>, <code>v2.0.0</code>) remain immutable Registry history. A host has no obligation to keep serving a withdrawn lane; a client that needs one pins the provider release that speaks it and the history that defines it.</p>',17)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
